$reportDelta=static function(int $current,int $previous)use($reportE):string{
    if($previous===0)return $current===0?'0,0 %':'<span title="'.$reportE('Bei einem Vorjahreswert von 0 € ist keine prozentuale Veränderung berechenbar.').'" aria-label="'.$reportE('Keine prozentuale Veränderung berechenbar: Vorjahr null Euro').'">–</span>';
    $value=($current-$previous)/abs($previous)*100;
    return e(($value>0?'+':'').number_format($value,1,',','.').' %');
};
