    <?php foreach($chartRows as $index=>$row):$groupCenter=$chartLeft+($index+.5)*$chartStep;$barSeries=[['income_cents',$reportT('Einnahmen'),'income',$row],['expense_cents',$reportT('Ausgaben'),'expense',$row]];if($reportCompare)$barSeries=[['income_cents',$reportT('Einnahmen'),'income',$row],['income_cents',$reportT('Einnahmen Vorjahr'),'income previous',$row['previous']??[]],['expense_cents',$reportT('Ausgaben'),'expense',$row],['expense_cents',$reportT('Ausgaben Vorjahr'),'expense previous',$row['previous']??[]]];foreach($barSeries as $barIndex=>[$amountKey,$barLabel,$barClass,$values]):$value=(int)($values[$amountKey]??0);$height=abs($value)/$chartRange*($chartBottom-$chartTop);$barY=$value>=0?$chartZero-$height:$chartZero;$x=$groupCenter-count($barSeries)*($chartBarWidth+3)/2+$barIndex*($chartBarWidth+3); ?><rect x="<?= round($x,2) ?>" y="<?= round($barY,2) ?>" width="<?= $chartBarWidth ?>" height="<?= round($height,2) ?>" rx="2" class="report-bar <?= $barClass ?>"><title><?= e($reportLabel($row).' · '.$barLabel.': '.euro($value)) ?></title></rect><?php endforeach ?><text x="<?= round($groupCenter,2) ?>" y="<?= $chartBottom+24 ?>" text-anchor="middle" class="report-axis-label report-axis-period"><?= e($reportResolution==='month'?($reportMonths[(int)substr($row['from'],5,2)-1].' '.substr($row['from'],0,4)):$reportAxisLabel($row)) ?></text><?php endforeach ?>
    </svg></div><?php if(!$chartHasValues): ?><p class="report-chart-empty"><?= $reportE('Keine Einnahmen oder Ausgaben im gewählten Zeitraum.') ?></p><?php endif ?></section>
    <?php
    $reportBreakdown=$report['breakdowns']??$report['breakdown']??[];
    $reportDonuts=[['key'=>'income','title'=>$reportT('Einnahmen'),'total'=>(int)$reportTotals['income_cents'],'items'=>$reportBreakdown['income']??[['label'=>$reportT('Einnahmen gesamt'),'amount_cents'=>(int)$reportTotals['income_cents']]]],['key'=>'expense','title'=>$reportT('Ausgaben'),'total'=>(int)$reportTotals['expense_cents'],'items'=>$reportBreakdown['expense']??[['label'=>$reportT('Ausgaben gesamt'),'amount_cents'=>(int)$reportTotals['expense_cents']]]],['key'=>'result','title'=>$reportT('Summe'),'total'=>(int)$reportTotals['result_cents'],'items'=>[['label'=>$reportT('Einnahmen'),'amount_cents'=>(int)$reportTotals['income_cents']],['label'=>$reportT('Ausgaben'),'amount_cents'=>(int)$reportTotals['expense_cents']]]]];
    $donutColors=['#172f58','#7fc4ed','#5278a6','#bddbeb','#355277','#9fb7d1'];
    ?><div class="report-total-cards"><?php foreach($reportDonuts as $donut):$donutAmounts=array_map(static fn(array $item):int=>(int)$item['amount_cents'],$donut['items']);$donutBase=array_sum($donutAmounts);$donutHasNegative=count(array_filter($donutAmounts,static fn(int $amount):bool=>$amount<0))>0;$donutOffset=0; ?><section class="report-total-card report-total-<?= $donut['key'] ?>"><div><h3><?= e($donut['title']) ?></h3><strong><?= e($reportMoney($donut['key']==='expense'?-$donut['total']:$donut['total'])) ?></strong></div><?php if($donutHasNegative): ?><p class="report-donut-note"><?= $reportE('Korrekturen enthalten') ?><br><span><?= $reportE('Anteile siehe Beträge') ?></span></p><?php else: ?><svg viewBox="0 0 120 120" class="report-donut" role="img" aria-label="<?= e($donut['title'].': '.$reportMoney($donut['key']==='expense'?-$donut['total']:$donut['total'])) ?>"><circle cx="60" cy="60" r="44" fill="none" stroke="#e7edf3" stroke-width="16"/><?php foreach($donut['items'] as $itemIndex=>$item):$share=$donutBase>0?(int)$item['amount_cents']/$donutBase*100:0;if($share>0): ?><circle cx="60" cy="60" r="44" fill="none" stroke="<?= $donutColors[$itemIndex%count($donutColors)] ?>" stroke-width="16" pathLength="100" stroke-dasharray="<?= $share ?> <?= 100-$share ?>" stroke-dashoffset="<?= -$donutOffset ?>" transform="rotate(-90 60 60)"><title><?= $reportE($item['label']).': '.e($reportMoney(($donut['key']==='expense'||($donut['key']==='result'&&$item['label']===$reportT('Ausgaben')))?-(int)$item['amount_cents']:(int)$item['amount_cents'])) ?></title></circle><?php endif;$donutOffset+=$share;endforeach ?></svg><?php endif ?><ul><?php if(!$donut['items']): ?><li><?= $reportE('Keine Zahlungen') ?></li><?php endif ?><?php foreach($donut['items'] as $itemIndex=>$item): ?><li><svg viewBox="0 0 10 10" width="9" height="9" aria-hidden="true"><circle cx="5" cy="5" r="5" fill="<?= $donutColors[$itemIndex%count($donutColors)] ?>"/></svg><span><?= $reportE($item['label']) ?></span><b><?= e($reportMoney(($donut['key']==='expense'||($donut['key']==='result'&&$item['label']===$reportT('Ausgaben')))?-(int)$item['amount_cents']:(int)$item['amount_cents'])) ?></b></li><?php endforeach ?></ul></section><?php endforeach ?></div>
    <?php endif ?>
</div>
</form>
